//! The Cargo lockfiles a checkout commits, and the crates.io packages each
//! one resolves.
//!
//! Only a tracked lockfile is read: it is what a build of the committed source
//! resolves, while an untracked one belongs to a build tree or a scratch
//! export and is regenerated by whoever builds there.

use crate::common::capture;
use anyhow::{bail, Context, Result};
use std::{
    collections::BTreeMap,
    path::{Path, PathBuf},
    process::Command,
};

/// The lockfile name Cargo writes beside a workspace's root manifest.
pub const LOCKFILE: &str = "Cargo.lock";

/// The manifest beside a lockfile that `cargo update` resolves it from.
pub const MANIFEST: &str = "Cargo.toml";

/// The two ways a lockfile names the crates.io registry as a package's source.
const CRATES_IO_SOURCES: &[&str] = &[
    "registry+https://github.com/rust-lang/crates.io-index",
    "sparse+https://index.crates.io/",
];

/// One package a lockfile resolves from crates.io, and the packages of the
/// same lockfile that depend on it.
#[derive(Clone, Debug)]
pub struct Package {
    pub name: String,
    pub version: String,
    pub dependents: Vec<String>,
}

/// Every lockfile `checkout` tracks, as paths relative to it, in path order.
pub fn tracked(checkout: &Path) -> Result<Vec<String>> {
    let output = capture(Command::new("git").arg("-C").arg(checkout).args([
        "ls-files",
        "-z",
        "--",
        &format!(":(glob){LOCKFILE}"),
        &format!(":(glob)**/{LOCKFILE}"),
    ]))?;
    if !output.status.success() {
        bail!(
            "git ls-files in {} failed ({}): {}",
            checkout.display(),
            output.status,
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    let listing = String::from_utf8(output.stdout)
        .with_context(|| format!("git ls-files in {} is not UTF-8", checkout.display()))?;
    let mut files: Vec<String> = listing
        .split('\0')
        .filter(|entry| !entry.is_empty())
        .map(str::to_owned)
        .collect();
    files.sort();
    files.dedup();
    Ok(files)
}

/// The package a lockfile's `dependencies` entry names, and the version it
/// names when it names one. Cargo writes `name` alone when the lock holds one
/// version of it, and `name version` (with its source when two sources share
/// the version) when it holds several.
fn depended(entry: &str) -> (String, String) {
    match entry.split_once(' ') {
        None => (entry.to_owned(), String::new()),
        Some((name, rest)) => match rest.split_once(' ') {
            None => (name.to_owned(), rest.to_owned()),
            Some((version, _source)) => (name.to_owned(), version.to_owned()),
        },
    }
}

/// The crates.io packages `lockfile` resolves, in name and version order.
/// A package from a git source or a path is not in a registry's advisory
/// database and is left out.
pub fn packages(lockfile: &Path) -> Result<Vec<Package>> {
    let text = std::fs::read_to_string(lockfile)
        .with_context(|| format!("reading the lockfile {}", lockfile.display()))?;
    let document: toml::Value = toml::from_str(&text)
        .with_context(|| format!("{}: not a Cargo lockfile", lockfile.display()))?;
    let entries = document
        .get("package")
        .and_then(toml::Value::as_array)
        .with_context(|| {
            format!(
                "{}: not a Cargo lockfile: it holds no [[package]] list, and a lockfile always \
                 holds at least the workspace's own packages",
                lockfile.display()
            )
        })?;
    let mut dependents: BTreeMap<(String, String), Vec<String>> = BTreeMap::new();
    let mut found = Vec::new();
    for entry in entries {
        let field = |name: &str| -> Result<String> {
            entry
                .get(name)
                .and_then(toml::Value::as_str)
                .map(str::to_owned)
                .with_context(|| format!("{}: a [[package]] has no {name}", lockfile.display()))
        };
        let (name, version) = (field("name")?, field("version")?);
        for dependency in entry
            .get("dependencies")
            .and_then(toml::Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(toml::Value::as_str)
        {
            dependents
                .entry(depended(dependency))
                .or_default()
                .push(format!("{name} {version}"));
        }
        let source = entry.get("source").and_then(toml::Value::as_str);
        if source.is_some_and(|source| CRATES_IO_SOURCES.contains(&source)) {
            found.push(Package {
                name,
                version,
                dependents: Vec::new(),
            });
        }
    }
    for package in &mut found {
        let mut named: Vec<String> = [package.version.clone(), String::new()]
            .into_iter()
            .filter_map(|at| dependents.get(&(package.name.clone(), at)))
            .flatten()
            .cloned()
            .collect();
        named.sort();
        named.dedup();
        package.dependents = named;
    }
    found.sort_by(|left, right| (&left.name, &left.version).cmp(&(&right.name, &right.version)));
    Ok(found)
}

/// The directory a lockfile sits in, where `cargo update` runs against the
/// manifest beside it.
pub fn directory(checkout: &Path, lockfile: &str) -> Result<PathBuf> {
    let path = checkout.join(lockfile);
    path.parent()
        .map(Path::to_path_buf)
        .with_context(|| format!("the lockfile {} names no directory", path.display()))
}
